function drawDetailChart(values,rain){const canvas=document.getElementById('detailChart'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=42,times=analysis.manifest.hourly.times,boundary=analysis.manifest.forecast_start_index||0,line=analysis.mode==='farm'?35:analysis.mode==='ground'?20:30,x=i=>pad+i*(w-pad*2)/(values.length-1);ctx.clearRect(0,0,w,h);ctx.fillStyle='#e8f1f8';ctx.fillRect(x(boundary),pad,w-pad-x(boundary),h-pad*2);ctx.strokeStyle='#d5dfdc';ctx.lineWidth=1;ctx.font='12px sans-serif';ctx.fillStyle='#60716d';for(let v=0;v<=100;v+=25){const y=h-pad-v*(h-pad*2)/100;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-pad,y);ctx.stroke();ctx.fillText(`${v}%`,4,y+4)}const lineY=h-pad-line*(h-pad*2)/100;ctx.strokeStyle='#d95f02';ctx.setLineDash([7,5]);ctx.beginPath();ctx.moveTo(pad,lineY);ctx.lineTo(w-pad,lineY);ctx.stroke();ctx.setLineDash([]);ctx.fillText(`水やりライン ${line}%`,pad+4,lineY-5);ctx.strokeStyle='#23735f';ctx.lineWidth=4;ctx.beginPath();values.forEach((v,i)=>{const y=h-pad-v*(h-pad*2)/100;i?ctx.lineTo(x(i),y):ctx.moveTo(x(i),y)});ctx.stroke();ctx.fillStyle='#4a90d9aa';rain.forEach((v,i)=>ctx.fillRect(x(i)-3,h-pad-Math.min(50,v)*2,6,Math.min(50,v)*2));ctx.fillStyle='#17352f';for(let i=0;i<times.length;i+=12)ctx.fillText(new Date(times[i]).toLocaleString('ja-JP',{day:'numeric',hour:'numeric'}),x(i)-16,h-8);ctx.fillText('うるおい残量（線）／雨量（棒）',pad,22)}
