const DB_NAME='water_care',DB_VERSION=1,STORE='items';let dbPromise;
function openDb(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(STORE))db.createObjectStore(STORE,{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return dbPromise}
async function getItems(){const db=await openDb();return new Promise((resolve,reject)=>{const request=db.transaction(STORE).objectStore(STORE).getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function putItem(item){const db=await openDb();return new Promise((resolve,reject)=>{const request=db.transaction(STORE,'readwrite').objectStore(STORE).put(item);request.onsuccess=()=>resolve();request.onerror=()=>reject(request.error)})}
async function deleteItem(id){const db=await openDb();return new Promise((resolve,reject)=>{const request=db.transaction(STORE,'readwrite').objectStore(STORE).delete(id);request.onsuccess=()=>resolve();request.onerror=()=>reject(request.error)})}
async function wateringTime(item){if(!analysis.manifest||item.mode==='medaka')return '--';if(analysis.landClasses&&!isPublicLandGrid(item.grid_id))return'再選択してください';const files=analysis.manifest.hourly.files[item.mode],moisture=await buffer(files.moisture,Uint8Array),n=analysis.manifest.grid_count,count=analysis.manifest.hourly.times.length,start=analysis.manifest.current_index||0,line=item.mode==='farm'?35:item.mode==='ground'?20:30,current=moisture[start*n+item.grid_id],boost=item.logs.some(log=>log.type==='water_full')?Math.max(0,95-current):item.logs.some(log=>log.type==='water_light')?40:0;for(let h=start;h<count;h++){if(Math.min(100,moisture[h*n+item.grid_id]+boost)<=line)return new Date(analysis.manifest.hourly.times[h]).toLocaleString('ja-JP',{month:'numeric',day:'numeric',hour:'numeric'})}return '提供期間内は未到達'}
async function itemStatus(item){if(!analysis.manifest)return '読込中';if(analysis.landClasses&&!isPublicLandGrid(item.grid_id))return'陸域マスク外（旧登録）';if(item.mode==='medaka')return 'メダカ容器';const refs=analysis.manifest.hourly.files[item.mode],n=analysis.manifest.grid_count,i=(analysis.manifest.current_index||0)*n+item.grid_id,[moisture,labels]=await Promise.all([buffer(refs.moisture,Uint8Array),buffer(refs.labels,Uint8Array)]);return `${moisture[i]}%・${labelText(labels[i])}`}
async function renderItems(){const items=await getItems(),container=document.getElementById('itemList');if(!items.length){container.innerHTML='<p>まだ登録がありません。</p>';return}const rows=[];for(const item of items){const medaka=item.mode==='medaka',outside=Boolean(analysis.landClasses)&&!isPublicLandGrid(item.grid_id),actions=outside?'':medaka?`<button class="water" data-log-id="${item.id}" data-log-type="water_change">水換え</button><button data-log-id="${item.id}" data-log-type="top_up">足し水</button><button data-log-id="${item.id}" data-log-type="rain_cover">雨よけ</button>`:`<button class="water" data-log-id="${item.id}" data-log-type="water_full">たっぷり水やり</button><button data-log-id="${item.id}" data-log-type="water_light">軽く水やり</button><button data-log-id="${item.id}" data-log-type="rain_cover">雨よけ</button>`,status=await itemStatus(item),next=outside?'地図上の陸域を再選択してください':`${medaka?'雨対策':'水やり目安'} ${await wateringTime(item)}`;rows.push(`<article class="item-row"><div><strong>${escapeText(item.name)}</strong><span>${escapeText(item.mode)}｜格子 ${item.grid_id}｜${status}｜${next}</span></div>${actions}<button data-delete-id="${item.id}">削除</button></article>`)}container.innerHTML=rows.join('');container.querySelectorAll('[data-log-id]').forEach(button=>button.addEventListener('click',()=>recordWater(button.dataset.logId,button.dataset.logType)));container.querySelectorAll('[data-delete-id]').forEach(button=>button.addEventListener('click',async()=>{await deleteItem(button.dataset.deleteId);renderItems()}))}
function escapeText(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
async function recordWater(id,type){const items=await getItems(),item=items.find(row=>row.id===id);if(!item)return;item.logs.push({ts:new Date().toISOString(),type,note:''});item.updated_at=new Date().toISOString();await putItem(item);renderItems()}
document.getElementById('itemForm').addEventListener('submit',async event=>{event.preventDefault();if(analysis.selectedGrid===null){setStatus('先に全国MAPで格子を選択してください');return}if(!isPublicLandGrid(analysis.selectedGrid)){setStatus('陸域マスク外の旧地点です。地図上の陸域を選び直してください');return}const items=await getItems();if(items.length>=20){setStatus('登録上限は20件です');return}const now=new Date().toISOString(),item={id:crypto.randomUUID(),name:document.getElementById('itemName').value.trim(),mode:document.getElementById('itemMode').value,location:{grid_id:analysis.selectedGrid,label:`格子 ${analysis.selectedGrid}`},grid_id:analysis.selectedGrid,preset_id:document.getElementById('itemPreset').value,simple_adjust:{dryness:document.getElementById('itemDryness').value,rain_exposure:document.getElementById('itemRain').value,sun:'full',wet_weakness:'normal',watering_stance:'std',wind:'std'},advanced_overrides:{},logs:[],observations:[],correction:{dry_speed_factor:1,rain_eff_factor:1},reserved_dry_stress:null,created_at:now,updated_at:now};await putItem(item);event.target.reset();document.getElementById('itemGrid').value=`格子 ${analysis.selectedGrid}`;renderItems()});
document.getElementById('exportItems').addEventListener('click',async()=>{const payload={schema_version:1,notice:'location情報（約5km格子ID）が含まれます。生の緯度経度は含みません。',items:await getItems()};const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));link.download='water_care-mydata.json';link.click();URL.revokeObjectURL(link.href)});
document.getElementById('importItems').addEventListener('change',async event=>{const data=JSON.parse(await event.target.files[0].text());if(data.schema_version!==1||!Array.isArray(data.items))throw new Error('対応していないJSONです');for(const item of data.items.slice(0,20)){if(!Number.isInteger(item.grid_id)||item.grid_id<0||item.grid_id>=analysis.manifest.grid_count||item.location?.lat!==undefined||item.location?.lon!==undefined)throw new Error('位置情報契約に違反するJSONです');await putItem(item)}renderItems()});
