async function copyText(text){try{await navigator.clipboard.writeText(text);return true}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();const ok=document.execCommand('copy');area.remove();return ok}}
document.getElementById('copyLink').addEventListener('click',async()=>{const url=new URL("https://nature-wx-lab.github.io/water_care/"),target=selectedTarget();url.search='';url.searchParams.set('layer',analysis.kind);url.searchParams.set('mode',analysis.mode);if(target.timeSemantics==='window')url.searchParams.set('aggregate',target.id);else url.searchParams.set('time',target.validtime_jst);url.searchParams.set('base',activeBase);url.searchParams.set('op',Math.round(analysis.opacity*100));url.searchParams.set('z',map.getZoom());url.searchParams.set('c',['mapPlant','mapSize','mapDrying','mapRain','mapSun','mapSpeed','mapWet'].map(id=>document.getElementById(id).value).join(','));if(analysis.selectedGrid!==null)url.searchParams.set('grid',analysis.selectedGrid);const button=document.getElementById('copyLink');button.dataset.lastUrl=url.toString();button.dataset.viewKind=analysis.viewKind;button.dataset.validtime=target.validtime_jst;const ok=await copyText(url.toString());button.textContent=ok?'コピー済み':'コピー失敗';setTimeout(()=>button.textContent='リンクコピー',1200)});
function drawExportLegend(ctx,width){const title=document.getElementById('legendTitle').textContent,labels=[document.getElementById('legendHigh').textContent,document.getElementById('legendMid').textContent,document.getElementById('legendLow').textContent],colors=analysis.kind==='moisture'?['#1f5fa8','#a8d08d','#b5651d']:analysis.kind==='watering'?['#a23b3b','#2d87c8','#d95f02']:['#c62828','#f2c84b','#74add1'];ctx.fillStyle='#fffffff0';ctx.fillRect(width-155,58,143,112);ctx.fillStyle='#17352f';ctx.font='bold 12px sans-serif';ctx.fillText(title,width-145,76);ctx.font='10px sans-serif';labels.forEach((label,i)=>{ctx.fillStyle=colors[i];ctx.fillRect(width-145,87+i*24,18,14);ctx.fillStyle='#17352f';ctx.fillText(label,width-120,98+i*24)})}
document.getElementById('saveImage').addEventListener('click',async()=>{const button=document.getElementById('saveImage');try{const mapElement=document.getElementById('map'),rect=mapElement.getBoundingClientRect(),scale=2,out=document.createElement('canvas'),target=selectedTarget();out.width=Math.round(rect.width*scale);out.height=Math.round(rect.height*scale);const ctx=out.getContext('2d');ctx.scale(scale,scale);ctx.fillStyle='#fff';ctx.fillRect(0,0,rect.width,rect.height);const images=[...mapElement.querySelectorAll('.leaflet-tile-loaded')];await Promise.all(images.map(image=>image.decode?.().catch(()=>{})));let skippedExternal=0;for(const image of images){const r=image.getBoundingClientRect();try{ctx.drawImage(image,r.left-rect.left,r.top-rect.top,r.width,r.height)}catch{skippedExternal++}}if(analysis.canvas)ctx.drawImage(analysis.canvas,0,0,rect.width,rect.height);if(amedasRain.canvas&&!amedasRain.canvas.hidden)ctx.drawImage(amedasRain.canvas,0,0,rect.width,rect.height);drawExportLegend(ctx,rect.width);const notes=[];if(suikeiWeatherLayer||rainMotionLabel)notes.push('気象庁外部タイルはブラウザ制約により保存画像で一部省略される場合があります');if(skippedExternal)notes.push(`外部タイル ${skippedExternal}枚を保存画像から省略`);if(notes.length){ctx.fillStyle='#fff7e8f5';ctx.fillRect(10,12,Math.min(rect.width-20,560),20+notes.length*16);ctx.fillStyle='#6a3b00';ctx.font='11px sans-serif';notes.forEach((note,index)=>ctx.fillText(note,18,32+index*16))}ctx.fillStyle='#fffffff0';ctx.fillRect(10,rect.height-58,Math.min(rect.width-20,520),48);ctx.fillStyle='#17352f';ctx.font='bold 14px sans-serif';ctx.fillText('Nature Wx Lab｜うるおい管理ナビ',18,rect.height-38);ctx.font='11px sans-serif';const observed=amedasRain.enabled?`｜${amedasRain.label}`:suikeiWeatherLayer?'｜推計気象分布（最新）':'';ctx.fillText(`${target.label} ${shortJst(target.validtime_jst)}｜${target.source}｜格子 ${analysis.selectedGrid??'未選択'}${observed}｜出典: 気象庁データを加工`,18,rect.height-20);const link=document.createElement('a'),fileId=target.timeSemantics==='window'?target.id:new Date(target.validtime_jst).toISOString().replace(/[-:]/g,'').slice(0,13);link.href=out.toDataURL('image/png');link.download=`water_care-map-${fileId}.png`;button.dataset.imageReady=`${out.width}x${out.height}`;button.dataset.imageLegend=document.getElementById('legendTitle').textContent;button.dataset.imageViewKind=analysis.viewKind;button.dataset.imageValidtime=target.validtime_jst;button.dataset.imageSlotLabel=target.label;button.dataset.skippedExternal=String(skippedExternal);button.dataset.imageNotes=notes.join(' / ');delete button.dataset.imageError;link.click();button.textContent='保存済み'}catch(error){button.dataset.imageError=error.name;button.textContent='保存失敗';console.error(error)}setTimeout(()=>button.textContent='画像保存',1200)});
